#!/usr/bin/env bash
#
# Creates the Android release signing key plus the android/keystore.properties
# file that android/app/build.gradle reads.
#
# Run this ONCE, per machine that needs to produce a release build, and reuse the
# resulting keystore forever. It is the app's permanent signing identity: lose it
# and you can never ship an update to an existing install again, because both
# Play Store uploads and in-place sideload upgrades require the same key. Back it
# up somewhere outside this repository.
#
# Neither generated file is committed — android/.gitignore excludes both.
#
#   ./scripts/generate-android-keystore.sh
#
set -euo pipefail

cd "$(dirname "$0")/.."

KEYSTORE="android/app/table-for-two-release.jks"
PROPS="android/keystore.properties"
ALIAS="tablefortwo"

KEYTOOL="$(command -v keytool || true)"
if [ -z "$KEYTOOL" ] && [ -x ".toolchain/jdk/bin/keytool" ]; then
  KEYTOOL="$PWD/.toolchain/jdk/bin/keytool"
fi
if [ -z "$KEYTOOL" ]; then
  echo "error: keytool not found." >&2
  echo "Install a JDK 17+ (Capacitor 8's Gradle build uses JDK 21) and retry." >&2
  exit 1
fi

if [ -f "$KEYSTORE" ]; then
  echo "error: $KEYSTORE already exists — refusing to overwrite." >&2
  echo "Replacing it would change the app's signing identity and break updates to" >&2
  echo "existing installs. Delete it deliberately if that is genuinely what you want." >&2
  exit 1
fi

# A random password keeps the script one-step, but override either value by
# exporting KEYSTORE_PASSWORD / KEY_PASSWORD before running it.
STORE_PASSWORD="${KEYSTORE_PASSWORD:-$(head -c 48 /dev/urandom | base64 | tr -d '/+=\n' | head -c 28)}"
KEY_PASSWORD="${KEY_PASSWORD:-$STORE_PASSWORD}"

mkdir -p "$(dirname "$KEYSTORE")"

"$KEYTOOL" -genkeypair -v \
  -keystore "$KEYSTORE" \
  -alias "$ALIAS" \
  -keyalg RSA -keysize 2048 -validity 10000 \
  -storetype PKCS12 \
  -storepass "$STORE_PASSWORD" \
  -keypass "$KEY_PASSWORD" \
  -dname "CN=Table for Two, O=Benjamin Goddard, C=US"

cat > "$PROPS" <<EOF
# Generated by scripts/generate-android-keystore.sh — DO NOT COMMIT.
# Read by android/app/build.gradle. storeFile is resolved relative to android/app/.
storeFile=table-for-two-release.jks
storePassword=$STORE_PASSWORD
keyAlias=$ALIAS
keyPassword=$KEY_PASSWORD
EOF

chmod 600 "$PROPS" "$KEYSTORE"

cat <<EOF

Release keystore created.
  keystore : $KEYSTORE
  alias    : $ALIAS
  password : $STORE_PASSWORD

Store that password somewhere safe now — it is not recoverable.

To let CI sign releases, add these repository secrets
(GitHub → Settings → Secrets and variables → Actions → New repository secret):

  ANDROID_KEYSTORE_BASE64  = \$(base64 -w0 $KEYSTORE)
  ANDROID_KEYSTORE_PASSWORD = $STORE_PASSWORD
  ANDROID_KEY_ALIAS         = $ALIAS
  ANDROID_KEY_PASSWORD      = $KEY_PASSWORD

Without them the release workflow still builds a sideloadable APK, but it is
signed with the debug key and cannot go to the Play Store.
EOF
